<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
(function () {
  /* ───────── palette (matched to source figure) ───────── */
  var CURVE = '#2ba6de';
  var FILL = '#cbe6f3';
  var INK = '#111111';
  var GAPC = 'rgba(238,124,44,0.55)';

  /* ───────── world window shared by every panel ───────── */
  var WX0 = -0.7, WX1 = 11.2, WY0 = -0.95, WY1 = 5.9;
  var A = 1.5, B = 8.5;            // interval [a,b]
  var CX0 = 0.32, CX1 = 10.2;      // drawn extent of the curve

  /* ───────── the curve: PCHIP through shape control points ───────── */
  var KX = [0.0, 0.6, 1.5, 2.5, 3.4, 4.2, 4.97, 5.8, 6.54, 7.3, 8.5, 9.2, 9.8, 10.2];
  var KY = [0.55, 1.27, 2.43, 3.90, 4.60, 4.35, 3.21, 2.35, 2.03, 2.12, 2.52, 3.30, 4.30, 5.10];
  var KD = (function () {
    var n = KX.length, h = [], del = [], d = new Array(n), i;
    for (i = 0; i < n - 1; i++) { h[i] = KX[i + 1] - KX[i]; del[i] = (KY[i + 1] - KY[i]) / h[i]; }
    d[0] = del[0]; d[n - 1] = del[n - 2];
    for (i = 1; i < n - 1; i++) {
      if (del[i - 1] * del[i] <= 0) d[i] = 0;
      else {
        var w1 = 2 * h[i] + h[i - 1], w2 = h[i] + 2 * h[i - 1];
        d[i] = (w1 + w2) / (w1 / del[i - 1] + w2 / del[i]);
      }
    }
    return d;
  })();

  function f(x) {
    var n = KX.length;
    if (x <= KX[0]) return KY[0] + KD[0] * (x - KX[0]);
    if (x >= KX[n - 1]) return KY[n - 1] + KD[n - 1] * (x - KX[n - 1]);
    var i = 0;
    while (i < n - 2 && x > KX[i + 1]) i++;
    var h = KX[i + 1] - KX[i], t = (x - KX[i]) / h, t2 = t * t, t3 = t2 * t;
    return (2 * t3 - 3 * t2 + 1) * KY[i] + (t3 - 2 * t2 + t) * h * KD[i] +
      (-2 * t3 + 3 * t2) * KY[i + 1] + (t3 - t2) * h * KD[i + 1];
  }

  function simpson(a, b, n) {
    if (n % 2) n++;
    var h = (b - a) / n, s = f(a) + f(b);
    for (var i = 1; i < n; i++) s += f(a + i * h) * ((i % 2) ? 4 : 2);
    return s * h / 3;
  }
  var EXACT = simpson(A, B, 4000);

  function riemann(n, rule) {
    var dx = (B - A) / n, s = 0;
    for (var i = 0; i < n; i++) {
      var x0 = A + i * dx;
      var xs = rule === 'left' ? x0 : (rule === 'right' ? x0 + dx : x0 + dx / 2);
      s += f(xs);
    }
    return s * dx;
  }

  /* ───────── state ───────── */
  var state = { n: 6, single: false, rule: 'mid' };

  /* ───────── canvas + Chart.js host ───────── */
  var container = document.getElementById('container');
  var canvas = document.createElement('canvas');
  canvas.style.cssText = 'width:100%;height:100%;display:block';
  container.appendChild(canvas);

  var panels = [], hitRects = [];

  var figPlugin = {
    id: 'riemannFigure',
    afterDraw: function (chart) {
      var a = chart.chartArea;
      if (!a || a.right - a.left < 10) return;
      drawFigure(chart.ctx, a);
    }
  };

  var chart = new Chart(canvas.getContext('2d'), {
    type: 'scatter',
    data: { datasets: [{ data: [] }] },
    options: {
