  window.__markRendered();

  document.addEventListener('fig-resize', function () { chart.resize(); });

  /* ───────── layout ───────── */
  function mkMap(p) {
    var sx = p.w / (WX1 - WX0), sy = p.h / (WY1 - WY0);
    return {
      sx: sx, sy: sy,
      X: function (wx) { return p.x + (wx - WX0) * sx; },
      Y: function (wy) { return p.y + p.h - (wy - WY0) * sy; }
    };
  }

  function layout(area) {
    var W = area.right - area.left, H = area.bottom - area.top, out = [];
    if (state.single) {
      out.push({ x: area.left, y: area.top, w: W, h: H * 0.98, kind: 'rects', n: state.n, caption: null, capH: H * 0.02, gaps: true, readout: true });
    } else {
      var gap = W * 0.025, pw = (W - 2 * gap) / 3, capH = H * 0.13, ph = H - capH;
      var nc = Math.max(2, Math.min(300, Math.round(state.n * 20 / 6)));
      out.push({ x: area.left, y: area.top, w: pw, h: ph, kind: 'exact', caption: '(a)', capH: capH });
      out.push({ x: area.left + pw + gap, y: area.top, w: pw, h: ph, kind: 'rects', n: state.n, caption: '(b)', capH: capH });
      out.push({ x: area.left + 2 * (pw + gap), y: area.top, w: pw, h: ph, kind: 'rects', n: nc, caption: '(c)', capH: capH });
    }
    return out;
  }

  /* ───────── primitives ───────── */
  function arrow(ctx, x1, y1, x2, y2, lw, size) {
    ctx.strokeStyle = INK; ctx.lineWidth = lw; ctx.lineCap = 'butt';
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
    var ang = Math.atan2(y2 - y1, x2 - x1);
    ctx.beginPath(); ctx.moveTo(x2, y2);
    ctx.lineTo(x2 - size * Math.cos(ang - 0.36), y2 - size * Math.sin(ang - 0.36));
    ctx.lineTo(x2 - size * Math.cos(ang + 0.36), y2 - size * Math.sin(ang + 0.36));
