    var axW = Math.max(0.8, S * 0.0045);
    var cW = Math.max(1.3, S * 0.0085);
    var hair = Math.max(0.45, S * 0.0028);
    var fs = Math.max(9, S * 0.062);
    var steps = Math.max(80, Math.round(p.w / 1.5));

    /* region / rectangles */
