    } else {
      var n = p.n, dx = (B - A) / n, y0 = m.Y(0);
      var sub = Math.max(3, Math.min(14, Math.round(90 / n) + 3));
      for (var i = 0; i < n; i++) {
        var xa = A + i * dx, xb = xa + dx;
        var xs = state.rule === 'left' ? xa : (state.rule === 'right' ? xb : xa + dx / 2);
        var hgt = f(xs);
        var X1 = m.X(xa), X2 = m.X(xb), Yt = m.Y(hgt);
        ctx.fillStyle = FILL;
        ctx.fillRect(X1, Yt, X2 - X1, y0 - Yt);
        ctx.strokeStyle = INK; ctx.lineWidth = hair;
        ctx.strokeRect(X1, Yt, X2 - X1, y0 - Yt);
        /* warm slivers: the leftover error between staircase and curve */
        if (p.gaps) {
          ctx.fillStyle = GAPC;
          for (var k = 0; k < sub; k++) {
            var u0 = xa + (xb - xa) * k / sub, u1 = xa + (xb - xa) * (k + 1) / sub;
            ctx.beginPath();
            ctx.moveTo(m.X(u0), Yt);
            ctx.lineTo(m.X(u0), m.Y(f(u0)));
            ctx.lineTo(m.X(u1), m.Y(f(u1)));
            ctx.lineTo(m.X(u1), Yt);
            ctx.closePath(); ctx.fill();
          }
        }
        hitRects.push({
          x: Math.min(X1, X2), y: Math.min(Yt, y0), w: Math.abs(X2 - X1), h: Math.abs(y0 - Yt),
          tip: 'Rectangle ' + (i + 1) + ' of ' + n + ':  height f(' + xs.toFixed(3) + ') = ' +
            hgt.toFixed(3) + ',  width Δx = ' + dx.toFixed(3) + ',  area = ' + (hgt * dx).toFixed(4),
          pop: {
            t: 'One rectangle of the Riemann sum',
            b: 'This bar has width Δx = (b−a)/n = ' + dx.toFixed(4) + ' and height f(x*) = ' +
              hgt.toFixed(4) + ', where x* is the ' + ruleName() + ' of the subinterval. Its area, ' +
              (hgt * dx).toFixed(4) + ', is one term of the sum Σ f(x*)Δx. No single bar matches the curved region above it — the orange sliver is the leftover error.'
          }
        });
      }
    }

    /* axes */
    arrow(ctx, m.X(-0.45), m.Y(0), m.X(10.75), m.Y(0), axW, Math.max(4, S * 0.028));
    arrow(ctx, m.X(0), m.Y(-0.35), m.X(0), m.Y(5.45), axW, Math.max(4, S * 0.028));

    /* curve */
    ctx.beginPath();
    curveTo(ctx, m, CX0, CX1, steps);
    ctx.strokeStyle = CURVE; ctx.lineWidth = cW; ctx.lineJoin = 'round'; ctx.lineCap = 'round';
    ctx.stroke();

    /* boundary verticals at a and b */
    ctx.strokeStyle = INK; ctx.lineWidth = Math.max(0.6, S * 0.0035);
    ctx.beginPath();
    ctx.moveTo(m.X(A), m.Y(0)); ctx.lineTo(m.X(A), m.Y(f(A)));
    ctx.moveTo(m.X(B), m.Y(0)); ctx.lineTo(m.X(B), m.Y(f(B)));
    ctx.stroke();

    /* labels (drawn last, on top) */
    ctx.fillStyle = INK;
    ctx.font = 'italic ' + fs.toFixed(1) + 'px "Times New Roman", Times, serif';
    ctx.textAlign = 'center'; ctx.textBaseline = 'alphabetic';
    ctx.fillText('a', m.X(A), m.Y(0) + fs * 1.05);
    ctx.fillText('b', m.X(B), m.Y(0) + fs * 1.05);
    ctx.fillText('x', m.X(10.2), m.Y(0) - fs * 0.45);
    ctx.textAlign = 'left';
    ctx.fillText('y', m.X(0) + fs * 0.35, m.Y(5.25));

    if (p.caption) {
      ctx.textAlign = 'center';
      ctx.font = 'italic ' + (fs * 1.05).toFixed(1) + 'px "Times New Roman", Times, serif';
      ctx.fillText(p.caption, p.x + p.w / 2, p.y + p.h + p.capH * 0.72);
    }

    /* readout (single-panel mode) */
    if (p.readout) drawReadout(ctx, p, S);
  }

  function drawReadout(ctx, p, S) {
    var sum = riemann(state.n, state.rule);
    var err = Math.abs(sum - EXACT);
    var fs = Math.max(9, S * 0.042);
    var lines = [
      'n = ' + state.n + '   (' + ruleName() + ')',
      'Σ f(x*)Δx  ≈ ' + sum.toFixed(4),
      'exact area ≈ ' + EXACT.toFixed(4),
      '|error|    ≈ ' + err.toFixed(4)
    ];
    ctx.font = fs.toFixed(1) + 'px ui-monospace, Consolas, monospace';
    var wmax = 0;
    for (var i = 0; i < lines.length; i++) wmax = Math.max(wmax, ctx.measureText(lines[i]).width);
    var pad = fs * 0.6;
    var bw = wmax + pad * 2 + fs * 1.4, bh = lines.length * fs * 1.35 + pad * 2 + fs * 1.3;
    var bx = p.x + p.w - bw - fs * 0.6, by = p.y + fs * 0.4;
    ctx.fillStyle = 'rgba(255,255,255,0.92)';
    ctx.fillRect(bx, by, bw, bh);
    ctx.strokeStyle = '#c9ced3'; ctx.lineWidth = 1;
    ctx.strokeRect(bx, by, bw, bh);
    ctx.fillStyle = '#17364a'; ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
    for (var j = 0; j < lines.length; j++) {
      ctx.fillText(lines[j], bx + pad, by + pad + fs * (1 + j * 1.35));
    }
    var ly = by + pad + fs * (1 + lines.length * 1.35) - fs * 0.75;
    ctx.fillStyle = GAPC;
    ctx.fillRect(bx + pad, ly, fs * 0.9, fs * 0.9);
    ctx.fillStyle = '#5a5a5a';
    ctx.fillText(' = leftover gap (the error)', bx + pad + fs * 1.0, ly + fs * 0.82);
  }

  function ruleName() {
    return state.rule === 'left' ? 'left endpoint' : (state.rule === 'right' ? 'right endpoint' : 'midpoint');
  }

  function drawFigure(ctx, area) {
    hitRects.length = 0;
    panels = layout(area);
    for (var i = 0; i < panels.length; i++) {
      panels[i].map = mkMap(panels[i]);
      drawPanel(ctx, panels[i]);
    }
  }

  function redraw() { chart.update('none'); updateSumReadout(); }

  /* ───────── hover / click ───────── */
  function pick(x, y) {
    var i;
    for (i = hitRects.length - 1; i >= 0; i--) {
      var h = hitRects[i];
      if (x >= h.x && x <= h.x + h.w && y >= h.y && y <= h.y + h.h) return h;
    }
    for (i = 0; i < panels.length; i++) {
      var p = panels[i];
      if (x < p.x || x > p.x + p.w || y < p.y || y > p.y + p.h) continue;
      var wx = (x - p.x) / p.map.sx + WX0;
      if (wx >= CX0 && wx <= CX1) {
        var cy = p.map.Y(f(wx));
        if (Math.abs(y - cy) <= Math.max(5, p.h * 0.018)) {
          return {
            tip: 'The curve y = f(x)  —  f(' + wx.toFixed(2) + ') = ' + f(wx).toFixed(3),
            pop: {
              t: 'The curve y = f(x)',
              b: 'Every rectangle top is forced to touch this curve at one sample point. Because the curve is not flat across a subinterval, each rectangle misses part of the region — but those misses shrink as the rectangles get thinner.'
            }
          };
        }
      }
      if (p.kind === 'exact' && wx > A && wx < B && y > p.map.Y(f(wx)) && y < p.map.Y(0)) {
        return {
          tip: 'Exact area under y = f(x) from a to b ≈ ' + EXACT.toFixed(4),
          pop: {
            t: 'The exact region — panel (a)',
            b: 'This is the area we want: everything between the curve and the x-axis on [a, b]. No elementary formula applies, so we define its area as the limit of the rectangle sums shown in panels (b) and (c). That limit is written ∫ₐᵇ f(x) dx.'
          }
        };
      }
    }
    return null;
  }

  canvas.addEventListener('mousemove', function (e) {
    var r = canvas.getBoundingClientRect();
    var hit = pick(e.clientX - r.left, e.clientY - r.top);
    if (hit) { canvas.style.cursor = 'pointer'; showTooltip(hit.tip, e); }
    else { canvas.style.cursor = 'default'; hideTooltip(); }
  });
  canvas.addEventListener('mouseleave', function () { hideTooltip(); });
  canvas.addEventListener('click', function (e) {
    var r = canvas.getBoundingClientRect();
    var hit = pick(e.clientX - r.left, e.clientY - r.top);
    if (hit && hit.pop) showPopup(hit.pop.t, hit.pop.b);
    else showPopup('Area as a limit',
      'The staircase of rectangles never equals the shaded region. The area is defined as the number the sums Σ f(x*)Δx are forced to approach as n → ∞ and Δx → 0 — and that limit is exactly the definite integral ∫ₐᵇ f(x) dx.');
  });

  /* ───────── UI readout ───────── */
  function pad(s, n) { s = String(s); while (s.length < n) s += ' '; return s; }
  function updateSumReadout() {
    var el = document.getElementById('sumReadout');
    if (!el) return;
    var L = riemann(state.n, 'left'), M = riemann(state.n, 'mid'), R = riemann(state.n, 'right');
    var cur = state.rule === 'left' ? L : (state.rule === 'right' ? R : M);
    var mark = function (k) { return state.rule === k ? ' ←' : ''; };
    el.textContent =
      pad('n', 8) + state.n + '        Δx = ' + ((B - A) / state.n).toFixed(4) + '\n' +
      pad('left', 8) + L.toFixed(4) + mark('left') + '\n' +
      pad('mid', 8) + M.toFixed(4) + mark('mid') + '\n' +
      pad('right', 8) + R.toFixed(4) + mark('right') + '\n' +
      pad('exact', 8) + EXACT.toFixed(4) + '\n' +
      pad('|err|', 8) + Math.abs(cur - EXACT).toFixed(4);
  }

  /* ───────── interaction handlers ───────── */
  window.update_rectangleCount = function (v) { state.n = Math.max(1, Math.round(v)); redraw(); };
  window.toggle_viewMode = function (on) { state.single = !!on; redraw(); };
  window.toggle_sampleRule = function (v) { state.rule = v; redraw(); };

  /* ───────── demo steps ───────── */
  var steps = [
    {
      title: 'The exact region',
      narration: 'Panel (a) shows the region we want to measure: everything between the blue curve and the x-axis from a to b. There is no elementary formula for this shape. Panels (b) and (c) already hint at the plan — cover it with rectangles.',
      state: { viewMode: false, rectangleCount: 6, sampleRule: 'mid' }
    },
    {
      title: 'A coarse approximation',
      narration: 'Switch to one panel and drop in six rectangles whose tops touch the curve. The staircase already resembles the region, but obvious orange gaps and overhangs remain — this is panel (b).',
      state: { viewMode: true, rectangleCount: 6, sampleRule: 'mid' }
    },
    {
      title: 'Refining the partition',
      narration: 'Push n upward and watch each rectangle narrow. The error readout falls quickly even though the total shaded area barely moves — the staircase is closing on the curve, not growing.',
      state: { viewMode: true, rectangleCount: 20, sampleRule: 'mid' }
    },
    {
      title: 'Does the sample point matter?',
      narration: 'At n = 20 switch the rectangle heights to left endpoints: individual bars shift up or down, yet the total changes only slightly. The rule for choosing heights is not what determines the answer.',
      state: { viewMode: true, rectangleCount: 20, sampleRule: 'left' }
    },
    {
      title: 'Toward the limit',
      narration: 'At n = 100 the rectangles are visually indistinguishable from the shaded region of panel (a), and left, midpoint and right sums agree to several decimals. That common limiting value is defined to be the area: ∫ₐᵇ f(x) dx.',
      state: { viewMode: true, rectangleCount: 100, sampleRule: 'left' }
    }
  ];
  var cur = 0;

  function applyStep(i) {
    cur = Math.max(0, Math.min(steps.length - 1, i));
    var s = steps[cur], st = s.state;
    var slider = document.getElementById('rectangleCountInput');
    slider.value = st.rectangleCount;
    document.getElementById('rectangleCountVal').value = st.rectangleCount;
    state.n = st.rectangleCount;
    var chk = document.getElementById('viewModeInput');
    chk.checked = st.viewMode;
    state.single = st.viewMode;
    var sel = document.getElementById('sampleRuleInput');
    sel.value = st.sampleRule;
    state.rule = st.sampleRule;
    document.getElementById('demoNarration').innerHTML =
      '<b>' + s.title + '</b><br>' + s.narration;
    document.getElementById('stepLabel').textContent = 'Step ' + (cur + 1) + ' / ' + steps.length;
    redraw();
  }
  window.nextStep = function () { applyStep(cur + 1); };
  window.prevStep = function () { applyStep(cur - 1); };

  applyStep(0);
})();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using Chart.js.

CONCEPT: The area under a curve on [a, b] is defined as the limit of sums of inscribed rectangle areas: as the number of rectangles n grows, the staircase approximation converges to the exact area.
KEY INSIGHT (what students should walk away understanding): The rectangles never equal the area — the area is what their total is forced to approach as the rectangles become infinitely thin, which is exactly what the definite integral means.
DEMO STEPS: 5 guided steps — implement the step player in #ui

